<?php
namespace App\Modules\Inventory\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Inventory\Domain\ValueObjects\StockAdjustmentData;use App\Modules\Inventory\Domain\ValueObjects\StockReservationData;use App\Modules\Inventory\Application\UseCases\AdjustInventory;use App\Modules\Inventory\Application\UseCases\ListInventory;use App\Modules\Inventory\Application\UseCases\ReleaseInventory;use App\Modules\Inventory\Application\UseCases\ReserveInventory;use App\Modules\Inventory\Presentation\Http\Requests\InventoryRequest;use Illuminate\Http\JsonResponse;
final class InventoryController extends Controller{public function index(InventoryRequest $request,ListInventory $useCase):JsonResponse{return response()->json(['data'=>$useCase->execute()]);}public function adjust(InventoryRequest $request,AdjustInventory $useCase):JsonResponse{return response()->json(['data'=>$useCase->execute(StockAdjustmentData::fromArray($request->validated()),$request->user())]);}public function reserve(InventoryRequest $request,ReserveInventory $useCase):JsonResponse{return response()->json(['data'=>$useCase->execute(StockReservationData::fromArray($request->validated()))]);}public function release(InventoryRequest $request,ReleaseInventory $useCase):JsonResponse{return response()->json(['data'=>$useCase->execute(StockReservationData::fromArray($request->validated()))]);}}
